mapper.select:
SELECT gld.customer_id AS organizationId, CONCAT_WS(' ', customers.customer_code, '-', customers.name) AS organizationName, gl.date AS `date`, CONCAT(gld.type, ' - ', gl.reference) AS `transaction`, CASE WHEN gld.debit > 0 THEN gld.debit ELSE gld.credit * -1 END AS amount, ( SELECT COALESCE(SUM(CASE WHEN gld2.debit > 0 THEN gld2.debit ELSE gld2.credit * -1 END), 0) FROM general_ledgers gl2 INNER JOIN general_ledger_details gld2 ON gl2.id = gld2.general_ledger_id WHERE gl2.is_approve = 1 AND gl2.is_active = 1 AND gld2.customer_id = gld.customer_id AND gld2.chart_account_id IN ( SELECT id FROM chart_accounts WHERE is_active = 1 AND chart_account_type_id IN ( SELECT id FROM chart_account_types WHERE name = 'Accounts Receivable' ) )
AND gl2.date >= #{filter.dateFrom}
AND gl2.date <= #{filter.dateTo}
AND (gl2.date < gl.date OR (gl2.date = gl.date AND gl2.id <= gl.id)) ) AS balance FROM general_ledgers gl INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id INNER JOIN customers ON gld.customer_id = customers.id WHERE gl.is_approve = 1 AND gl.is_active = 1 AND
AND gl.date >= #{filter.dateFrom}
AND gl.date <= #{filter.dateTo}
AND gld.customer_id = #{filter.organizationId}
ORDER BY gld.customer_id ASC, gl.date ASC, gl.id ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(gl.id)
FROM general_ledgers gl
INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id
INNER JOIN customers ON gld.customer_id = customers.id
WHERE gl.is_approve = 1
AND gl.is_active = 1
AND 

    AND gl.date >= #{filter.dateFrom}


    AND gl.date <= #{filter.dateTo}


    AND gld.customer_id = #{filter.organizationId}

SELECT COALESCE(
SUM(
    CASE
        WHEN gld.debit > 0 AND gl.credit_memo_receipt_id IS NULL THEN gld.debit
        ELSE 0
    END
) +
SUM(
    CASE
        WHEN gld.debit > 0 AND gl.credit_memo_id IN (
            SELECT credit_memo_id FROM general_ledgers
            WHERE is_active = 1
            AND customer_id = #{customerId}
            AND DATEDIFF(#{filter.dateTo}, date) BETWEEN #{fromDays} AND #{toDays}
            AND credit > 0
            AND sales_order_id IS NULL
            AND main_gl_id IS NULL
        ) THEN gld.debit
        ELSE 0
    END
) -
SUM(
    CASE
        WHEN gld.credit > 0 AND (
            gl.sales_order_id IN (
                SELECT sales_order_id FROM general_ledgers
                WHERE is_active = 1
                AND customer_id = #{customerId}
                AND DATEDIFF(#{filter.dateTo}, date) BETWEEN #{fromDays} AND #{toDays}
                AND debit > 0
                AND credit_memo_receipt_id IS NULL
            )
            OR gld.main_gl_id IN (
                SELECT id FROM general_ledgers
                WHERE is_active = 1
                AND customer_id = #{customerId}
                AND DATEDIFF(#{filter.dateTo}, date) BETWEEN #{fromDays} AND #{toDays}
                AND debit > 0
                AND credit_memo_receipt_id IS NULL
            )
        ) THEN gld.credit
        ELSE 0
    END
) -
SUM(
    CASE
        WHEN gld.credit > 0 AND gl.sales_order_id IS NULL AND gld.main_gl_id IS NULL THEN gld.credit
        ELSE 0
    END
), 0
) AS amount
FROM general_ledgers gl
INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id
WHERE gl.is_active = 1
AND 
AND gld.customer_id = #{customerId}
AND DATEDIFF(#{filter.dateTo}, gl.date) BETWEEN #{fromDays} AND #{toDays}
AND gl.date <= #{filter.dateTo}

SELECT COALESCE(
SUM(
    CASE
        WHEN gld.debit > 0 AND gl.credit_memo_receipt_id IS NULL THEN gld.debit
        ELSE 0
    END
) +
SUM(
    CASE
        WHEN gld.debit > 0 AND gl.credit_memo_id IN (
            SELECT credit_memo_id FROM general_ledgers
            WHERE is_active = 1
            AND customer_id = #{customerId}
            AND DATEDIFF(#{filter.dateTo}, date) > #{throughDays}
            AND credit > 0
            AND sales_order_id IS NULL
            AND main_gl_id IS NULL
        ) THEN gld.debit
        ELSE 0
    END
) -
SUM(
    CASE
        WHEN gld.credit > 0 AND (
            gl.sales_order_id IN (
                SELECT sales_order_id FROM general_ledgers
                WHERE is_active = 1
                AND customer_id = #{customerId}
                AND DATEDIFF(#{filter.dateTo}, date) > #{throughDays}
                AND debit > 0
                AND credit_memo_receipt_id IS NULL
            )
            OR gld.main_gl_id IN (
                SELECT id FROM general_ledgers
                WHERE is_active = 1
                AND customer_id = #{customerId}
                AND DATEDIFF(#{filter.dateTo}, date) > #{throughDays}
                AND debit > 0
                AND credit_memo_receipt_id IS NULL
            )
        ) THEN gld.credit
        ELSE 0
    END
) -
SUM(
    CASE
        WHEN gld.credit > 0 AND gl.sales_order_id IS NULL AND gld.main_gl_id IS NULL THEN gld.credit
        ELSE 0
    END
), 0
) AS amount
FROM general_ledgers gl
INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id
WHERE gl.is_active = 1
AND 
AND gld.customer_id = #{customerId}
AND DATEDIFF(#{filter.dateTo}, gl.date) > #{throughDays}
AND gl.date <= #{filter.dateTo}
